# === G1 CLIMB: このセル1つで全部やります ===
# 事前にメニュー [ランタイム → ランタイムのタイプを変更 → T4 GPU] を選択しておくこと。
# 実行内容: GPU確認 → ライブラリ導入 → 学習環境を展開 → 150Mステップ学習(1〜2時間)
#           → 学習済みポリシー(g1_climb_params.pkl)を自動ダウンロード
import base64, os, subprocess, sys

# 1) GPU確認
r = subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True)
assert r.returncode == 0 and r.stdout.strip(), \
    "GPUがありません: メニュー[ランタイム→ランタイムのタイプを変更→T4 GPU]を選んで再実行"
print(r.stdout.strip())
print("✅ GPU OK")

# 2) MuJoCo Playground + JAX(CUDA)
os.system(f"{sys.executable} -m pip install -q playground 'jax[cuda12]'")
import jax
print("JAX devices:", jax.devices())

# 3) 学習環境+学習スクリプトを展開(base64埋め込み: リポジトリ取得不要)
open("g1_climb_mjx_env.py", "wb").write(base64.b64decode(""))
open("g1_train_colab.py", "wb").write(base64.b64decode(""))
print("✅ ファイル展開OK — 学習開始(eval reward が伸びていけば順調)")

# 4) 学習(T4で1〜2時間。途中経過は下に流れます)
rc = os.system(f"{sys.executable} g1_train_colab.py --task climb --steps 150_000_000 --out /content/g1_climb")
assert rc == 0, "学習が異常終了しました(上のログを確認)"

# 5) Macへダウンロード → models/policies/ に置いて g1_climb_play.py で検証
from google.colab import files
files.download("/content/g1_climb_params.pkl")
files.download("/content/g1_climb_config.json")
print("🎉 完了 — ダウンロードした g1_climb_params.pkl を Mac の models/policies/ へ")
